package com.github.rcubedev.utils.event.generated;

import com.github.rcubedev.utils.event.api.Cancellable;
import com.github.rcubedev.utils.event.api.Event;
import com.github.rcubedev.utils.event.api.EventProcessor;
import com.github.rcubedev.utils.event.impl.processor.WeakEventProcessor;
import org.jetbrains.annotations.ApiStatus;

/**
 * An instance invoker bound to its target event type, execution priority and
 * cancellation handling behaviour.
 *
 * @apiNote This interface is implemented solely by classes generated by the
 *          annotation processor and should not be implemented directly
 * @param <T> the listener type
 * @param <E> the specific event type handled
 */
@ApiStatus.Internal
public non-sealed interface InstanceSubscriberInvoker<T, E extends Event> extends EventSubscriberInvoker<T, E> {

    /**
     * Invokes the target handler method on the specified listener instance.
     *
     * @param listener the target listener instance
     * @param event the event to dispatch
     */
    void invoke(T listener, E event);

    /**
     * Indicates whether this handler should utilise a {@link java.lang.ref.WeakReference WeakReference}
     * to the listener.
     *
     * @return {@code true} if this handler requires a weak reference to the listener.
     * @implSpec Implementations must be side-effect-free. Successive calls must return
     *           the exact same result.
     */
    boolean isWeak();

    default EventProcessor<E> create(T listener) {
        boolean ignoreCancelled = ignoreCancelled();
        if (isWeak()) {
            return new WeakEventProcessor<>(listener, ignoreCancelled ? (instance, event) -> {
                if (!(event instanceof Cancellable c && c.isCancelled())) this.invoke(instance, event);
            } : this::invoke);
        }

        return ignoreCancelled ? e -> {
            if (e instanceof Cancellable c && c.isCancelled()) return;
            this.invoke(listener, e);
        } : e -> invoke(listener, e);
    }
}
